const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const brand = typeof $json.brand === 'string' ? $json.brand.trim().toLowerCase() : '';
const listName = typeof $json.listName === 'string' ? $json.listName.trim() : '';
const csvText = typeof $json.csvText === 'string' ? $json.csvText : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const brandPattern = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const statuses = ['imported', 'needs_review', 'enriched', 'emailed', 'opened', 'followed_up', 'replied', 'closed'];
const maxRows = 200;
let error = null;

if (!uuidPattern.test(sessionId)) {
  error = { code: 'INVALID_SESSION', message: 'The import proposal needs a valid conversation session.' };
} else if (brand === '' || brand.length > 40 || !brandPattern.test(brand)) {
  error = { code: 'INVALID_BRAND', message: 'Say which brand this list belongs to, such as oddtoe or datalabs.' };
} else if (listName === '' || listName.length > 120) {
  error = { code: 'INVALID_LIST', message: 'Give the list a short name, such as "Agency list Aug 2026".' };
} else if (csvText.trim() === '') {
  error = { code: 'EMPTY_IMPORT', message: 'There is no table text to import. Attach the CSV or paste the rows first.' };
} else if (csvText.length > 200000) {
  error = { code: 'IMPORT_TOO_LARGE', message: 'That table is too large. Import at most 200 rows at a time.' };
}

const warnings = [];
let rows = [];
if (!error) {
  const parseDelimited = (text, delimiter) => {
    const parsed = [];
    let row = [];
    let field = '';
    let inQuotes = false;
    for (let index = 0; index < text.length; index += 1) {
      const character = text[index];
      if (inQuotes) {
        if (character === '"') {
          if (text[index + 1] === '"') { field += '"'; index += 1; } else { inQuotes = false; }
        } else { field += character; }
      } else if (character === '"') {
        inQuotes = true;
      } else if (character === delimiter) {
        row.push(field); field = '';
      } else if (character === '\n') {
        row.push(field); parsed.push(row); row = []; field = '';
      } else if (character !== '\r') {
        field += character;
      }
    }
    if (field !== '' || row.length > 0) { row.push(field); parsed.push(row); }
    return parsed.filter((line) => line.some((cell) => cell.trim() !== ''));
  };
  const firstLine = csvText.split('\n', 1)[0] ?? '';
  const delimiter = (firstLine.match(/\t/g) ?? []).length >= (firstLine.match(/,/g) ?? []).length && firstLine.includes('\t') ? '\t' : ',';
  const table = parseDelimited(csvText, delimiter);
  if (table.length < 2) {
    error = { code: 'EMPTY_IMPORT', message: 'The table needs a header row plus at least one prospect row.' };
  } else {
    const headerMap = {
      '': 'rowNumber', 'no': 'rowNumber', 'row': 'rowNumber', 'rownumber': 'rowNumber',
      'company': 'company', 'companyname': 'company', 'agency': 'company',
      'region': 'region', 'location': 'region', 'city': 'region',
      'tier': 'tier',
      'source': 'source',
      'website': 'website', 'site': 'website', 'url': 'website',
      'linkedincompanyurl': 'linkedinCompanyUrl', 'companylinkedin': 'linkedinCompanyUrl', 'companylinkedinurl': 'linkedinCompanyUrl',
      'contactname': 'contactName', 'contact': 'contactName', 'name': 'contactName',
      'contactemail': 'contactEmail', 'email': 'contactEmail', 'emailaddress': 'contactEmail',
      'linkedinurl': 'linkedinUrl', 'linkedin': 'linkedinUrl',
      'pdfsent': 'pdfSent',
      'sentdate': 'sentDate', 'datesent': 'sentDate',
      'opened': 'opened',
      'followupsent': 'followUpSent', 'followup': 'followUpSent',
      'status': 'status',
      'notes': 'notes', 'note': 'notes', 'comments': 'notes'
    };
    const header = table[0].map((cell) => headerMap[cell.trim().toLowerCase().replace(/[^a-z0-9]/g, '')] ?? null);
    const unknownHeaders = table[0].filter((cell, index) => header[index] === null && cell.trim() !== '');
    if (!header.includes('company')) {
      error = { code: 'MISSING_COMPANY', message: 'The table needs a Company column.' };
    } else {
      if (unknownHeaders.length > 0) {
        warnings.push(`Ignored ${unknownHeaders.length} unrecognised column(s): ${unknownHeaders.slice(0, 5).join(', ')}.`);
      }
      const dataRows = table.slice(1);
      if (dataRows.length > maxRows) {
        error = { code: 'IMPORT_TOO_LARGE', message: `That table has ${dataRows.length} rows. Import at most ${maxRows} at a time.` };
      } else {
        let skippedNoCompany = 0;
        let invalidStatuses = 0;
        dataRows.forEach((cells, dataIndex) => {
          const record = {};
          header.forEach((field, columnIndex) => {
            if (field !== null && field !== 'rowNumber') {
              const value = (cells[columnIndex] ?? '').trim();
              if (value !== '') { record[field] = value.slice(0, field === 'notes' ? 1000 : 300); }
            } else if (field === 'rowNumber') {
              const value = Number.parseInt((cells[columnIndex] ?? '').trim(), 10);
              if (Number.isInteger(value)) { record.rowNumber = value; }
            }
          });
          if (typeof record.company !== 'string' || record.company === '') {
            skippedNoCompany += 1;
            return;
          }
          if (record.rowNumber === undefined) { record.rowNumber = dataIndex + 1; }
          if (record.status !== undefined) {
            const normalised = record.status.toLowerCase().replace(/[\s-]+/g, '_');
            if (statuses.includes(normalised)) {
              record.status = normalised;
            } else {
              invalidStatuses += 1;
              record.notes = record.notes ? `${record.notes} | Original status: ${record.status}` : `Original status: ${record.status}`;
              delete record.status;
            }
          }
          rows.push(record);
        });
        if (skippedNoCompany > 0) { warnings.push(`Skipped ${skippedNoCompany} row(s) with no company name.`); }
        if (invalidStatuses > 0) { warnings.push(`Moved ${invalidStatuses} unrecognised status value(s) into notes.`); }
        if (rows.length === 0) {
          error = { code: 'EMPTY_IMPORT', message: 'No usable prospect rows were found. Every row needs a company name.' };
        }
      }
    }
  }
}

const proposedInput = error ? {} : { brand, listName, rows };
const auditInput = { brand, listName, rowCount: rows.length, characterCount: csvText.length };
const actionId = error ? '' : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => { const random = Math.floor(Math.random() * 16); const value = character === 'x' ? random : (random & 0x3) | 0x8; return value.toString(16); });
const confirmationText = error ? '' : `CONFIRM ${actionId.replaceAll('-', '').slice(-8).toUpperCase()}`;
const expiresAt = error ? '' : new Date(Date.now() + 5 * 60 * 1000).toISOString();
return {
  json: {
    valid: error === null,
    sessionId,
    actionId,
    actionType: 'import_prospects',
    brand,
    listName,
    rowCount: rows.length,
    warnings,
    preview: rows.slice(0, 5).map((row) => row.company),
    proposedInput,
    auditInput,
    confirmationText,
    expiresAt,
    ...(error ? { response: { ok: false, error } } : {})
  }
};

const proposal = $('Validate Import Proposal').first().json;
if (!Number.isInteger($json.id)) {
  return {
    json: {
      ...proposal,
      response: {
        ok: false,
        error: {
          code: 'CONFIRMATION_DATA_UNAVAILABLE',
          message: 'The import proposal could not be saved. Rerun local setup, then try again.'
        }
      }
    }
  };
}
return {
  json: {
    ...proposal,
    response: {
      ok: true,
      confirmationRequired: true,
      action: {
        type: 'import_prospects',
        brand: proposal.brand,
        listName: proposal.listName,
        rowCount: proposal.rowCount,
        preview: proposal.preview,
        warnings: proposal.warnings
      },
      confirmation: {
        phrase: proposal.confirmationText,
        expiresAt: proposal.expiresAt
      },
      message: `No prospects changed. ${proposal.rowCount} row(s) are ready to import into "${proposal.listName}" for ${proposal.brand}. Ask the user to reply with exactly "${proposal.confirmationText}" within five minutes.`
    }
  }
};

const response = $json.response;
const error = response?.ok === false ? String(response.error?.message ?? 'Tool failed') : '';
return {
  json: {
    occurredAt: new Date().toISOString(),
    sessionId: String($json.sessionId ?? ''),
    requestId: String(''),
    toolName: 'propose_import_prospects',
    proposedInput: JSON.stringify($json.auditInput ?? $json.proposedInput ?? {}),
    result: JSON.stringify(response),
    error,
    response
  }
};

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
